/**
 * ヘルプのFAQ本文と用語集。
 *
 * もとは src/app/help/page.tsx の中にあったが、AIヘルプ（/api/ai/help）が
 * サーバー側から読む必要があるためここへ出した。
 *
 * ★アイコン（LucideIcon）はここに置かない。サーバーコンポーネントから import できなくなるため、
 *   カテゴリ id → アイコンの対応はページ側（help/page.tsx の CATEGORY_ICONS）に持つ。
 *
 * 機能を変えたらここのFAQも更新すること（プロジェクトの運用ルール）。
 * 書き方（どのフィールドに何を書くか・公開前の機能の扱い）は docs/help-authoring-guide.md。
 */

export type RoleTag = 'admin' | 'manager' | 'teacher' | 'all';

/**
 * その機能がいま使える状態か。省略時は 'live'（公開済み）。
 *
 * ★ roles と混ぜないこと。roles は「公開されたときに誰が使う機能か」（権限）で、
 *   status は「いま使えるか」（公開状態）。以前はこの2つを roles 一本で表そうとして
 *   未公開機能に roles: ['admin'] を付けており、AIヘルプのロール絞り込み
 *   （filterIndexByRole）が教室長から見出しごと落としてしまい、
 *   「載っていません」としか答えられなくなっていた。
 *
 * - 'live'    公開済み。誰でも（権限があれば）いま使える
 * - 'preview' 実装済みだが試作扱い。歯車メニューなど限られた入口から限られたロールだけ
 * - 'planned' 実装済みだが公開前。いまは画面を開いても使えない
 *
 * 公開したら status ごと消す（省略＝live）。statusNote も一緒に消すこと。
 */
export type FeatureStatus = 'live' | 'preview' | 'planned';

export interface FaqItem {
  question: string;
  answer: string;
  /** 画面までのナビゲーションパス（例: 'ヘッダー「生徒管理」→ 生徒一覧ページ'） */
  path?: string;
  /** 番号付き操作手順 */
  steps?: string[];
  /** 注意点・よくあるつまずき */
  tips?: string[];
  keywords?: string[];
  link?: { href: string; label: string };
  roles?: RoleTag[];
  /**
   * その機能の前提になっている決まり。1件1文で書く。
   *
   * ★steps（手順）と混ぜないこと。手順は「そのまま写す」もの、規則は
   *   「利用者が挙げた具体的な値に当てはめて答えてよい」もので、扱いが違う。
   *   AIヘルプは規則に限って当てはめを許し、そのとき使った規則を必ず答えに書く
   *   （前提が間違っていれば読んだ人が気づけるようにするため）。
   *
   * 例: 「月謝は翌月分を当月に請求する。『2026年9月請求』は10月に実施する授業の分」
   *     → 「12月請求は何月分？」に「翌月分なので2027年1月分です」と答えられる。
   *
   * 書かない規則は当てはめられない（AIは一般常識で補わず unanswered にする）ので、
   * 運用の前提が増えたらここに足すこと。
   */
  rules?: string[];
  /** いま使える状態か。省略＝'live'（公開済み） */
  status?: FeatureStatus;
  /** status が live でないときの一言（誰がどこから触れるか・いつ公開か）。AIはこれをそのまま伝える */
  statusNote?: string;
  /** 関連するFAQ項目のquestionテキスト（クロスリンク用） */
  related?: string[];
}

export interface FaqCategoryData {
  id: string;
  title: string;
  description: string;
  items: FaqItem[];
}

